        FOREIGN KEY (development_specialization_id)
            REFERENCES krrg_development_specializations(id) ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS idx_employee_profiles__development_specialization_id
    ON krrg_employee_profiles (development_specialization_id);

rollback.sql:
